(async()=>{const report=[],q=EmberQA,W=EmberTerrain;function check(ok,label){if(!ok)throw Error(label);report.push(label);}try{q.setPlaying(false);check(q.entities.every(e=>!e.boss),'ボスが出現しない');check(!q.world.sockets&&!q.world.shrineRamp&&q.world.deco.length===0,'祭壇・台座・ボス遺跡を生成しない');check(!W.inCave(W.sites.cave.x,W.sites.cave.z),'旧ボス洞窟の床と壁を撤去');check(W.islands.length===2,'ボス用の大きな浮島を撤去');check(W.caves.length===32&&q.world.caveGroups.length===32,'探索洞窟32か所を生成');check(q.world.floor(0,-7,W.shrine.y,q.state)===W.floor(0,-7,W.shrine.y),'祭壇跡に見えない床が残らない');
const legacy=q.snapshot();legacy.finalAwake=true;legacy.enemyStates.final={hp:850,deadUntil:0};q.apply(legacy);check(q.entities.every(e=>!e.boss),'過去のセーブからもボスを復活させない');
for(const c of W.caves){const seen=new Set(['4,8']),todo=[[4,8]];while(todo.length){const[x,z]=todo.pop();for(const[dx,dz]of[[1,0],[-1,0],[0,1],[0,-1]]){const key=(x+dx)+','+(z+dz);if(c.cellSet.has(key)&&!seen.has(key)){seen.add(key);todo.push([x+dx,z+dz]);}}}check(seen.size===c.cells.length&&!W.caveBlocked(c.x,c.z+22.4,c.y),c.name+'：入口と内部がつながっている');}
const c=[...W.caves].sort((a,b)=>Math.hypot(a.x,a.z+22.5+a.rampLength-24)-Math.hypot(b.x,b.z+22.5+b.rampLength-24))[0];q.state.x=c.x;q.state.z=c.z+22.5+c.rampLength+.5;q.state.y=q.world.floor(q.state.x,q.state.z,c.y,q.state);q.state.yaw=0;q.state.pitch=0;q.keys({});for(let n=0;n<125;n++){q.world.update(q.state.time,q.state,{day:.8});if(n%5===0)await new Promise(r=>setTimeout(r,0));}
q.camera.position.set(q.state.x,q.state.y+1.7,q.state.z);q.camera.rotation.set(0,0,0);q.close(false);q.hud();await new Promise(r=>setTimeout(r,1200));q.renderer.render(q.scene,q.camera);const entrance=q.renderer.domElement.toDataURL();q.keys({KeyW:true});for(let n=0;n<600&&q.state.z>c.z+17;n++)q.move(1/60);q.keys({});check(q.state.z<c.z+18&&W.inCave(q.state.x,q.state.z)&&Math.abs(q.state.y-c.y)<.05,'実際の歩行で南側スロープから洞窟内部に入れる');q.hud();q.renderer.render(q.scene,q.camera);const inside=q.renderer.domElement.toDataURL();const info={name:c.name,x:c.x,z:Math.round(c.z+22.5+c.rampLength),distance:Math.round(Math.hypot(c.x,c.z+22.5+c.rampLength-24)),checks:report.length};q.map();check(!document.querySelector('#modalBody').textContent.includes('守護者')&&document.querySelector('#modalBody').textContent.includes('入口座標'),'地図にボス表示がなく洞窟の入口案内がある');q.close(false);
const panel=document.createElement('section');panel.style='position:fixed;inset:0;z-index:9999;background:#10282d;overflow:auto;padding:16px';panel.innerHTML='<h1>PASS — 自由探索・洞窟の確認</h1><pre>'+JSON.stringify(info,null,2)+'</pre><p>'+report.join('<br>')+'</p><h2>実際の洞窟入口</h2><img style="width:80%" src="'+entrance+'"><h2>歩いて入った内部</h2><img style="width:80%" src="'+inside+'">';document.body.append(panel);
}catch(e){const panel=document.createElement('pre');panel.style='position:fixed;inset:0;z-index:9999;background:#400;color:white';panel.textContent='FAIL '+e.stack;document.body.append(panel);}})();
